 var ranges;
 let seed = Math.random() * 999999;
 var mySize, margin;
 let str_wei = 0;

 // colors
 let colors0 = "281914-1a1a1a-202020-242e30".split("-").map((a) => "#" + a);
 let colors1 = "fef9fb-fafdff-ffffff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
 let colors2 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
 let colors_cyber = "ee0cf2-352ef2-1df252-f2e41d".split("-").map((a) => "#" + a);
 let color1, color2;
 let colorselet = [];

 let newTone01 = "FF9494-FFD1D1-FFE3E1-FFF5E4".split("-").map((a) => "#" + a);
 let newTone02 = "967E76-D7C0AE-EEE3CB-B7C4CF".split("-").map((a) => "#" + a);
 let newTone03 = "EEF1FF-D2DAFF-AAC4FF-B1B2FF".split("-").map((a) => "#" + a);
 let newTone04 = "E38B29-F1A661-FFD8A9-FDEEDC".split("-").map((a) => "#" + a);
 let newTone05 = "FFC3A1-F0997D-D3756B-A75D5D".split("-").map((a) => "#" + a);
 let newTone06 = "374259-545B77-5C8984-F2D8D8".split("-").map((a) => "#" + a);
 let newTone07 = "675D50-ABC4AA-F3DEBA-A9907E".split("-").map((a) => "#" + a);
 let newTone08 = "F5F5F5-E8E2E2-F99417-5D3891".split("-").map((a) => "#" + a);
 let newTone09 = "EAE0DA-F7F5EB-A0C3D2-EAC7C7".split("-").map((a) => "#" + a);
 let newTone10 = "FFED00-16FF00-0F6292-202020".split("-").map((a) => "#" + a);
 let newTone11 = "82954B-BABD42-EFD345-FFEF82".split("-").map((a) => "#" + a);
 let newTone12 = "146C94-19A7CE-B0DAFF-FEFF86".split("-").map((a) => "#" + a);


 let pastel_bg = "ccd4bf-e7cba9-eebab2-f5f3f7-f5e2e4-f4c815-f9cad7-A57283-c1d5de-deede6-AAD9CD-E8D595-E9BBB5-E7CBA9-8DA47E-f7f6cf-b6d8f2-f4cfdf-9ac8eb".split("-").map((a) => "#" + a); //Mini Pastel Pops


 let unit;
 let count;
 let Cubes = [];

 function setup() {
 	randomSeed(seed);
 	let color_sel2 = random([newTone01, newTone02, newTone03, newTone04, newTone05, newTone06, newTone07, newTone08, newTone09, newTone10, newTone11, newTone12]);
 	mySize = max(windowWidth, windowHeight);
 	// mySize = 1000;
 	margin = mySize / 100;
 	createCanvas(windowWidth, windowHeight);
 	colorselet[0] = random(colors1);
 	colorselet[1] = random(colors0);
 	colorselet[2] = random(color_sel2);
 	colorselet[3] = random(color_sel2);
 	colorselet[4] = random(color_sel2);
 	colorselet[5] = random(color_sel2);
 	colorselet[6] = random(color_sel2);
 	unit = int(random(15, 8));

 	noStroke();
 	let wideCount = width / unit;
 	let highCount = height / unit;
 	count = wideCount * highCount;

 	let index = 0;
 	for (let y = 0; y < highCount; y++) {
 		for (let x = 0; x < wideCount; x++) {
 			Cubes[index++] = new Brush(
 				x * 1,
 				y * unit,
 				unit,
 				unit,
 				random(1, 0.25),
 				21 * unit / random(0.5, 2)
 			);
 		}
 	}
 	makeFilter();
 	background(random(colors1));
 }

 function draw() {
 	randomSeed(seed);
 	for (let i = 0; i < count; i++) {
 		Cubes[i].update();
 		Cubes[i].draw();
 	}
 	image(overAllTexture, 0, 0);
 }

 class Brush {
 	constructor(xOff, yOff, x, y, speed, unit) {
 		this.xOff = xOff * 2;
 		this.yOff = yOff * 2;
 		this.x = x;
 		this.y = y;
 		this.speed = speed * 1;
 		this.unit = unit;
 		this.xDir = 1;
 		this.yDir = 1;
 	}

 	update() {
 		this.x = this.x + this.speed * this.xDir * random(1, 2);
 		if (this.x >= this.unit || this.x <= 0) {
 			this.xDir *= -1;
 			this.x = this.x + 1 * this.xDir;
 			this.y = this.y + 1 * this.yDir;
 		}
 		if (this.y >= this.unit || this.y <= 0) {
 			this.yDir *= -1;
 			this.y = this.y + 1 * this.yDir;
 		}
 	}

 	draw() {
 		noFill();
 		stroke(str(random(colorselet)) + "33");
 		strokeWeight(random(2.5, 5) / 2);
 		// if (int(this.x) % 5 == 0) {
 		// 	noStroke();
 		// 	fill(str(random(colorselet)) + "33");
 		// }
 		drawingContext.shadowColor = str(random([colors0, colors1])) + "80";
 		drawingContext.shadowOffsetX = 1;
 		drawingContext.shadowOffsetY = 1;
 		drawingContext.shadowBlur = 0;
 		let y_size = 1 * random(height / 4, height / 2) * noise(sin(this.x), cos(this.y), frameCount * 0.001);
 		push();
 		translate(random(-width * 0.2, width * 1.2), 0);
 		arc(this.x + this.xOff, this.y + this.yOff, this.xOff / random(8, 2), y_size / 0.5, -PI / random(2, 12), 0);
 		pop();
 	}
 }

 function makeFilter() {
 	randomSeed(seed);
 	// noiseのフィルターをつくる
 	colorMode(HSB, 360, 100, 100, 100);
 	drawingContext.shadowColor = color(0, 0, 5, 5);
 	overAllTexture = createGraphics(width, height);
 	overAllTexture.loadPixels();
 	for (var i = 0; i < width; i += 4) { // noprotect
 		for (var j = 0; j < height; j += 4) { // noprotect
 			overAllTexture.set(
 				i,
 				j,
 				color(0, 10, 70, noise(i / 3, j / 3, (i * j) / 50) * random(10, 25))
 			);
 		}
 	}
 	overAllTexture.updatePixels();
 }

// === Tab: save ===
function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("0708_untitled_2023", "png");
	}
}

